  function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function getShortBadge(catLabel) {
    if (!catLabel) return 'เรื่องเล่า';
    if (catLabel.indexOf('ช่างฝีมือ') !== -1) return 'ช่างฝีมือ';
    if (catLabel.indexOf('ของกิ๋น') !== -1) return 'ของกิ๋น';
    if (catLabel.indexOf('ตำนาน') !== -1) return 'ประเพณี';
    if (catLabel.indexOf('เที่ยว') !== -1) return 'ท่องเที่ยว';
    return catLabel.split('&')[0].trim();
  }

  function renderCard(v) {
    var badge = getShortBadge(v.categoryLabel);
    return [
      '<article class="tll-card" onclick="window.tllWatch(\'' + v.id + '\', \'' + escapeHtml(v.title) + '\', \'' + escapeHtml(v.channel) + '\', \'' + escapeHtml(v.district) + '\', \'' + badge + '\')">',
        '<div class="tll-thumb">',
          '<img src="' + v.thumb + '" alt="' + escapeHtml(v.title) + '" loading="lazy" decoding="async" onerror="this.src=\'https://i.ytimg.com/vi/' + v.id + '/hqdefault.jpg\'">',
          '<div class="tll-play-btn">',
            '<div class="tll-play-circle">',
              '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>',
            '</div>',
          '</div>',
          '<span class="tll-tag-cat">' + badge + '</span>',
          '<span class="tll-tag-len">' + v.length + '</span>',
        '</div>',
        '<div class="tll-body">',
          '<h3 class="tll-card-title">' + escapeHtml(v.title) + '</h3>',
          '<div class="tll-meta-row">',
            '<span class="tll-meta-channel">' + escapeHtml(v.channel) + '</span>',
            '<span class="tll-meta-dist">' + escapeHtml(v.district) + '</span>',
          '</div>',
        '</div>',
      '</article>'
    ].join('');
  }

